export function generateReadme(config: AppConfig): string {
  return `# ${config.appName} - Flutter App

Generated by **Web2App by joo.exe**
Target URL: \`${config.url}\`
Package Name: \`${config.packageName}\`

## Quick Start Guide

### Prerequisites
1. Install [Flutter SDK 3.x or later](https://docs.flutter.dev/get-started/install)
2. Install Android Studio (for Android builds) or Xcode (for iOS builds)

### How to Run the App
\`\`\`bash
# 1. Extract this zip folder
cd ${config.appName.toLowerCase().replace(/[^a-z0-9_]/g, '_')}

# 2. Fetch Flutter dependencies
flutter pub get

# 3. Launch on emulator or connected device
flutter run
\`\`\`

### How to Build Release APK / App Bundle
\`\`\`bash
# Build Android APK (Output in build/app/outputs/flutter-apk/app-release.apk)
flutter build apk --release

# Build Android App Bundle for Google Play
flutter build appbundle --release

# Build iOS Release
flutter build ios --release

# Build Flutter Web App
flutter build web --release
\`\`\`

## Features Included
- **Multi-Platform Support**: Android, iOS, Web, Windows, macOS
- **High-Performance WebView Engine**: Smooth scrolling and full JavaScript execution
- **Smart Connectivity Guard**: Live online/offline detection with custom retry screen
- **Pull to Refresh**: ${config.enablePullToRefresh ? 'Enabled' : 'Disabled'}
- **Android Hardware Back Button Handler**: Native back stack navigation
- **Custom Splash Screen**: Styled with brand colors and animated loader
`;
}

export function generateGithubWorkflow(config: AppConfig): string {
  const sanitizeName = (config.appName || 'app').toLowerCase().replace(/[^a-z0-9_]/g, '_') || 'app';
  return `name: Auto Build Flutter APK & Release

on:
  push:
    branches: [ main, master ]
  workflow_dispatch:

jobs:
  build:
    name: Build Release APK
    runs-on: ubuntu-latest

    steps:
      - name: Checkout Repository
        uses: actions/checkout@v4

      - name: Set up Java JDK 17
        uses: actions/setup-java@v4
        with:
          distribution: 'temurin'
          java-version: '17'

      - name: Set up Flutter SDK
        uses: subosito/flutter-action@v2
        with:
          flutter-version: '3.22.x'
          channel: 'stable'
          cache: true

      - name: Install Dependencies
        run: flutter pub get

      - name: Build Android APK
        run: flutter build apk --release

      - name: Upload APK Artifact
        uses: actions/upload-artifact@v4
        with:
          name: ${sanitizeName}-release-apk
          path: build/app/outputs/flutter-apk/app-release.apk
`;
}

